const ROOTS = ['custom', 'data', 'identity', 'llm', 'raw', 'schemaVersion'];

const compactArray = (value, path) => {
  if (value === null || value === undefined) return null;
  if (!Array.isArray(value)) throw new Error(`${path} must be an array or null`);
  return JSON.stringify(value);
};

const objectOrEmpty = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};

const locationLabel = (location) => {
  const value = objectOrEmpty(location);
  if (typeof value.raw === 'string' && value.raw.trim()) return value.raw.trim();
  return [...new Set([value.city, value.region, value.countryName].filter(part => typeof part === 'string' && part.trim()).map(part => part.trim()))].join(', ') || null;
};

const incoming = $input.all().map(item => item.json);
const jobs = [];
for (const value of incoming) {
  if (Array.isArray(value)) jobs.push(...value);
  else if (value && Array.isArray(value.body)) jobs.push(...value.body);
  else if (value && value.schemaVersion === 'nomad-agent-job-v1') jobs.push(value);
  else if (value && Object.keys(value).length === 0) continue;
  else throw new Error('Apify response did not contain nomad-agent-job-v1 records');
}

const seen = new Set();
const output = [];
for (const record of jobs) {
  if (!record || typeof record !== 'object' || Array.isArray(record)) throw new Error('Actor row must be an object');
  const actualRoots = Object.keys(record).sort();
  if (JSON.stringify(actualRoots) !== JSON.stringify(ROOTS)) throw new Error(`Actor row has unexpected roots: ${actualRoots.join(', ')}`);
  if (record.schemaVersion !== 'nomad-agent-job-v1') throw new Error(`Unsupported schemaVersion: ${record.schemaVersion}`);

  const identity = objectOrEmpty(record.identity);
  const data = objectOrEmpty(record.data);
  const company = objectOrEmpty(data.company);
  const classification = objectOrEmpty(data.classification);
  const employment = objectOrEmpty(data.employment);
  const application = objectOrEmpty(data.application);
  const seniority = objectOrEmpty(data.seniority);
  const compensation = objectOrEmpty(data.compensation);
  const llm = objectOrEmpty(record.llm);
  const raw = objectOrEmpty(record.raw);
  const locations = data.locations;
  if (locations !== null && locations !== undefined && !Array.isArray(locations)) throw new Error('data.locations must be an array or null');
  const firstLocation = Array.isArray(locations) && locations.length ? objectOrEmpty(locations[0]) : {};
  const stablePart = identity.externalId || identity.url;
  if (!identity.source || !stablePart) throw new Error('identity.source and identity.externalId or identity.url are required');
  const jobKey = `${identity.source}:${stablePart}`;
  if (seen.has(jobKey)) continue;
  seen.add(jobKey);

  output.push({ json: {
    schemaVersion: 'nomad-agent-flat-job-v1',
    jobKey,
    source: identity.source,
    identityExternalId: identity.externalId ?? null,
    jobUrl: identity.url ?? null,
    title: data.title ?? null,
    companyName: company.name ?? null,
    companySourceId: company.sourceId ?? null,
    companyUrl: company.url ?? null,
    locationText: Array.isArray(locations) ? locations.map(locationLabel).filter(Boolean).join(' | ') || null : null,
    countryCode: firstLocation.countryCode ?? null,
    city: firstLocation.city ?? null,
    region: firstLocation.region ?? null,
    workArrangements: compactArray(employment.workArrangements, 'data.employment.workArrangements'),
    workSchedules: compactArray(employment.workSchedules, 'data.employment.workSchedules'),
    contractTypes: compactArray(employment.contractTypes, 'data.employment.contractTypes'),
    postedAt: application.postedAt ?? null,
    applicationDeadline: application.deadline ?? null,
    applicationUrl: application.url ?? null,
    applicationEmail: application.email ?? null,
    directApply: application.directApply ?? null,
    seniorityLevels: compactArray(seniority.levels, 'data.seniority.levels'),
    industries: compactArray(classification.industries, 'data.classification.industries'),
    jobFunctions: compactArray(classification.jobFunctions, 'data.classification.jobFunctions'),
    salaryCurrency: compensation.currency ?? null,
    salaryExact: compensation.exact ?? null,
    salaryMinimum: compensation.minimum ?? null,
    salaryMaximum: compensation.maximum ?? null,
    salaryPeriod: compensation.period ?? null,
    salaryRaw: compensation.raw ?? null,
    descriptionText: raw.description ?? null,
    llmStatus: llm.status ?? null
  } });
}
return output;

const state = $getWorkflowStaticData('global');
const now = Date.now();
const retentionMs = 90 * 24 * 60 * 60 * 1000;
if (!state.seenJobs || typeof state.seenJobs !== 'object' || Array.isArray(state.seenJobs)) state.seenJobs = {};
for (const [key, timestamp] of Object.entries(state.seenJobs)) {
  if (typeof timestamp !== 'number' || now - timestamp > retentionMs) delete state.seenJobs[key];
}
return $input.all().filter(item => !state.seenJobs[item.json.jobKey]);

const state = $getWorkflowStaticData('global');
if (!state.seenJobs || typeof state.seenJobs !== 'object' || Array.isArray(state.seenJobs)) state.seenJobs = {};
const now = Date.now();
// Read the original rows only after the Sheets node succeeds; its output shape can vary.
const items = $('Filter previously delivered jobs').all();
for (const item of items) {
  if (item.json.jobKey) state.seenJobs[item.json.jobKey] = now;
}
const newest = Object.entries(state.seenJobs).sort((a, b) => b[1] - a[1]).slice(0, 5000);
state.seenJobs = Object.fromEntries(newest);
return items;

const rows = $input.all().map(item => item.json);
const escapeHtml = (value) => String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('\"', '&quot;');
let telegramText = `<b>${rows.length} new LinkedIn job${rows.length === 1 ? '' : 's'}</b>\n`;
for (const row of rows) {
  const title = escapeHtml(row.title || 'Untitled role');
  const company = escapeHtml(row.companyName || 'Unknown company');
  const location = escapeHtml(row.locationText || 'Location not specified');
  const url = escapeHtml(row.jobUrl || '');
  const block = `\n<a href=\"${url}\"><b>${title}</b></a>\n${company} - ${location}\n`;
  if (telegramText.length + block.length > 3500) {
    telegramText += `\n...and ${rows.length - rows.indexOf(row)} more in Google Sheets.`;
    break;
  }
  telegramText += block;
}
const emailText = rows.map(row => `${row.title || 'Untitled role'} | ${row.companyName || 'Unknown company'} | ${row.locationText || 'Location not specified'} | ${row.jobUrl || ''}`).join('\n');
return [{ json: { newJobCount: rows.length, telegramText, emailSubject: `${rows.length} new LinkedIn jobs`, emailText } }];
